import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for ConvTranspose1d
conv_transpose_source = '''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose_1d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int groups,
    int input_b_stride,
    int input_c_stride,
    int input_l_stride,
    int weight_ic_stride,
    int weight_oc_stride,
    int weight_k_stride,
    int output_b_stride,
    int output_c_stride,
    int output_l_stride
) {
    int op = blockIdx.x * blockDim.x + threadIdx.x;
    int oc = blockIdx.y * blockDim.y + threadIdx.y;
    int b = blockIdx.z * blockDim.z + threadIdx.z;

    if (b >= batch_size || oc >= out_channels || op >= output_length) {
        return;
    }

    int valid_length = (input_length - 1) * stride - 2 * padding + kernel_size;
    if (op >= valid_length) {
        return;
    }

    int out_channels_per_group = out_channels / groups;
    int in_channels_per_group = in_channels / groups;

    int g = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;

    int start_ic = g * in_channels_per_group;

    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int numerator = op - k + padding;
        if (numerator % stride != 0) {
            continue;
        }
        int ip = numerator / stride;
        if (ip < 0 || ip >= input_length) {
            continue;
        }

        for (int ic_in_group = 0; ic_in_group < in_channels_per_group; ++ic_in_group) {
            int ic = start_ic + ic_in_group;

            int input_idx = b * input_b_stride + ic * input_c_stride + ip * input_l_stride;
            float input_val = input[input_idx];

            int weight_idx = ic * weight_ic_stride + oc_in_group * weight_oc_stride + k * weight_k_stride;
            float weight_val = weight[weight_idx];

            sum += input_val * weight_val;
        }
    }

    int output_idx = b * output_b_stride + oc * output_c_stride + op * output_l_stride;
    output[output_idx] = sum;
}

torch::Tensor conv_transpose_1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int groups,
    int output_padding
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_length = input.size(2);

    auto out_channels = weight.size(1) * groups;
    auto kernel_size = weight.size(2);

    int output_length = (input_length - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, output_length}, input.options());

    input = input.contiguous();
    weight = weight.contiguous();

    auto input_ptr = input.data_ptr<float>();
    auto weight_ptr = weight.data_ptr<float>();
    auto output_ptr = output.data_ptr<float>();

    int input_b_stride = input.stride(0);
    int input_c_stride = input.stride(1);
    int input_l_stride = input.stride(2);

    int weight_ic_stride = weight.stride(0);
    int weight_oc_stride = weight.stride(1);
    int weight_k_stride = weight.stride(2);

    int output_b_stride = output.stride(0);
    int output_c_stride = output.stride(1);
    int output_l_stride = output.stride(2);

    dim3 block(16, 16, 4);
    dim3 grid(
        (output_length + block.x - 1) / block.x,
        (out_channels + block.y - 1) / block.y,
        (batch_size + block.z - 1) / block.z
    );

    conv_transpose_1d_kernel<<<grid, block>>>(
        input_ptr,
        weight_ptr,
        output_ptr,
        batch_size,
        in_channels,
        out_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding,
        groups,
        input_b_stride,
        input_c_stride,
        input_l_stride,
        weight_ic_stride,
        weight_oc_stride,
        weight_k_stride,
        output_b_stride,
        output_c_stride,
        output_l_stride
    );

    return output;
}
'''

conv_transpose_cpp_source = 'torch::Tensor conv_transpose_1d_cuda(torch::Tensor input, torch::Tensor weight, int stride, int padding, int groups, int output_padding);'

# Compile the inline CUDA code
conv_transpose_1d = load_inline(
    name='conv_transpose_1d',
    cpp_sources=conv_transpose_cpp_source,
    cuda_sources=conv_transpose_source,
    functions=['conv_transpose_1d_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O2']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        # Weight parameter
        self.weight = nn.Parameter(torch.Tensor(
            in_channels,
            out_channels // groups,
            kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output = conv_transpose_1d.conv_transpose_1d_cuda(
            x,
            self.weight,
            self.stride,
            self.padding,
            self.groups,
            self.output_padding
        )
        if self.bias is not None:
            output += self.bias.view(1, -1, 1)
        return output
